import {commerceProduct} from './commerce-catalog.js';
import {amazonHome,ecommercePage,travelPage,realEstatePage,financialPage,popularPage,socialPage,amazonPage,amazonTaskCopy} from './amazon.js';
import {economicsForm,economicsResult} from './economics-ui.js';
import {landing,publicShell,roleWelcome,examples,offerFor,offerCard,offerPreview} from './landing.js';
import {partnerWizard} from './partner-onboarding.js';
const root=document.querySelector('#app');
let activeCommerceId='amazon';
const commercePath=()=>activeCommerceId==='amazon'?'amazon':'commerce/'+activeCommerceId;
const onCommercePage=()=>path()==='product/'+activeCommerceId;
const freshCommerceState=()=>({connection:null,messages:[],answer:null,plan:null,quote:null,result:null,error:'',text:'',mode:'preview',image:null,run:null});
let amazonState={connection:null,messages:[],answer:null,plan:null,quote:null,result:null,error:'',text:'',mode:'preview',image:null,run:null};
let amazonRequestId=crypto.randomUUID();
function drawAmazon(){root.innerHTML=publicShell(amazonPage({...amazonState,product:commerceProduct(activeCommerceId)}),{user,active:commerceProduct(activeCommerceId).category==='Travel'?'travel':commerceProduct(activeCommerceId).category==='Real Estate'?'estate':commerceProduct(activeCommerceId).category==='Financial'?'financial':commerceProduct(activeCommerceId).category==='Social Media'?'social':commerceProduct(activeCommerceId).category==='Most Popular'?'popular':'catalog',realData:amazonState.connection?.execution?.enabled});}
async function openAmazon(id='amazon'){
 clearTimeout(amazonPollTimer);activeCommerceId=id;amazonState=freshCommerceState();amazonRequestId=crypto.randomUUID();amazonPollCount=0;
 const current=id,base=commercePath();document.title=commerceProduct(id).name+' — Affsiwen';drawAmazon();
 try{const [connection,workspace]=await Promise.all([api(base+'/connection'),api(base+'/workspace')]);if(current!==activeCommerceId||!onCommercePage())return;amazonState={...amazonState,connection,...workspace,error:''};if(!workspace.messages?.length){amazonState.plan=null;amazonState.quote=null;amazonState.result=null;}drawAmazon();scheduleAmazonPoll();}
 catch(e){if(current===activeCommerceId&&onCommercePage()){amazonState.error=e.message;drawAmazon();}}
}
async function sendAmazon(message){
 const current=activeCommerceId,base=commercePath();
 amazonState.text=message;amazonState.pending=true;amazonState.error='';drawAmazon();
 try{const result=await api(base+'/chat',{message,requestId:amazonRequestId,image:amazonState.image});if(current!==activeCommerceId||!onCommercePage())return;amazonState={...amazonState,...result,text:'',image:null};amazonRequestId=crypto.randomUUID();}
 catch(e){if(current===activeCommerceId)amazonState.error=e.message;}
 finally{if(current!==activeCommerceId)return;amazonState.pending=false;if(onCommercePage()){drawAmazon();root.querySelector('.amazon-offer')?.scrollIntoView({behavior:'smooth',block:'center'});root.querySelector('#amazon-message')?.focus({preventScroll:true});}}
}

let amazonPollTimer=null,amazonPollCount=0;
function scheduleAmazonPoll(){clearTimeout(amazonPollTimer);if(onCommercePage()&&['starting','running'].includes(amazonState.run?.status)&&amazonPollCount<60)amazonPollTimer=setTimeout(()=>pollAmazon(),10000);}
async function pollAmazon(){
 if(!onCommercePage())return;
 if(busy||document.hidden){scheduleAmazonPoll();return;}
 const current=activeCommerceId;try{amazonPollCount++;const response=await api(commercePath()+'/run/status');if(current!==activeCommerceId||!onCommercePage())return;amazonState.run=response.run;amazonState.result=response.run?.result||null;amazonState.error='';drawAmazon();}
 catch(e){if(current===activeCommerceId&&onCommercePage()){amazonState.error=e.message;drawAmazon();}}
 finally{if(current===activeCommerceId)scheduleAmazonPoll();}
}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR'}).format(n/100);
const count=n=>n===null||n===undefined?'—':new Intl.NumberFormat('ru-RU',{notation:'compact'}).format(n);
const date=v=>new Date(v).toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'});
const titles={home:'Главная',start:'Начало работы',partner:'Заявка партнёра',assistant:'Подобрать Agent',methodology:'Как мы оцениваем',catalog:'Каталог решений',orders:'Мои заказы',favorites:'Сохранённые',sourcing:'Отбор продуктов',operations:'Операции',analytics:'Экономика',economics:'Расчёт цены',launch:'Подключения',supply:'Предложить продукт',login:'Вход'};
const labels={candidate:'На отборе',published:'В каталоге · демо',paused:'Приостановлен',rejected:'Отклонён',awaiting_payment:'Ожидает оплаты',queued:'В очереди',starting:'Запускается',running:'Выполняется',delivered:'Результат готов',accepted:'Принят',review:'На проверке',reconciliation:'Нужна сверка запуска',refunded:'Возврат',cancelled:'Отменён'};
let user=null,health=null,products=[],orders=[],favorites=[],busy=false,filter='',category='Все',sort='popular',resultFilter='',pendingKey=crypto.randomUUID(),pendingOrder=null,routeRevision=0;
const roles={buyer:'Покупатель',supplier:'Партнёр',operator:'Оператор Affsiwen'};
const status=s=>`<span class="pill ${['delivered','accepted'].includes(s)?'green':['review','reconciliation','candidate'].includes(s)?'amber':'blue'}">${esc(labels[s]||s)}</span>`;
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json','X-Affsiwen-Request':'1'},body:data===undefined?undefined:JSON.stringify(data)});const out=await r.json();if(!r.ok)throw Error(out.error||'Ошибка запроса');return out;}
function toast(text,error=false){const n=document.querySelector('#toast');n.textContent=text;n.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.className='',6000);}
const path=()=>location.hash.slice(1)||'home';
let landingExample='companies',landingRole='buyer',partnerStep=1,partnerDraft={};
try{const d=JSON.parse(sessionStorage.getItem('affsiwen-partner-draft')||'null');if(d){partnerDraft=d.draft||{};partnerStep=[1,2,3].includes(d.step)?d.step:1;}}catch{}
const savePartner=()=>sessionStorage.setItem('affsiwen-partner-draft',JSON.stringify({draft:partnerDraft,step:partnerStep}));
let intakeState={messages:[],answer:null},intakeRequest=crypto.randomUUID(),intakeText='';
try{pendingOrder=JSON.parse(sessionStorage.getItem('affsiwen-draft')||'null');}catch{}
const saveDraft=()=>{if(pendingOrder)sessionStorage.setItem('affsiwen-draft',JSON.stringify(pendingOrder));else sessionStorage.removeItem('affsiwen-draft');};
function shell(content){const current=path().split('/')[0];if(!user&&['catalog','product'].includes(current)){root.innerHTML=publicShell(content,{user,active:'catalog'});return;}let nav=[['home','⌂'],['assistant','✧'],['catalog','▦'],['orders','◷'],['favorites','☆']];if(user?.role==='operator')nav.push(['sourcing','＋'],['operations','≡'],['analytics','↗'],['economics','€'],['launch','⚙']);if(user?.role==='supplier')nav=[['home','⌂'],['supply','＋'],['catalog','▦']];
root.innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><img src="assets/affsiwen-logo.svg" alt="Affsiwen"></a><div class="section-label">Data marketplace</div>${nav.map(([id,icon])=>`<a class="nav ${current===id?'active':''}" href="#${id}"><b>${icon}</b>${titles[id]}</a>`).join('')}<div class="side-foot"><strong>Affsiwen · Luxembourg</strong>Один заказ. Готовый результат.<br>Рабочее пространство платформы.</div></aside><div class="main"><header class="topbar"><span class="breadcrumb meta">Workspace / ${esc(titles[current]||'Результаты и продукты')}</span><div class="name"><span class="avatar">${user?'A':'↗'}</span>${user?`${esc(user.email)} <small>· ${roles[user.role]}</small>`:'Гостевой просмотр'}</div><div class="actions">${user?'<button class="text-button" data-action="logout">Выйти</button>':'<a class="primary" href="#login">Войти</a>'}</div></header><main><div class="banner">Демонстрационный режим исполнения: заказы и аккаунты сохраняются на сервере; результаты синтетические, цены сценарные, реальных списаний нет.</div>${content}</main><footer><span>Affsiwen Platform · собственная витрина и выдача</span><span><a href="#methodology">Как Affsiwen отбирает решения</a></span></footer></div>`;}
function heading(title,description='',actions=''){return `<div class="page-head"><div><div class="eyebrow">AFFSIWEN / ${esc(roles[user?.role]||'MARKET')}</div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,text,link='#catalog',label='Выбрать продукт'){return `<div class="empty"><h2>${title}</h2><p>${text}</p><a class="primary" href="${link}">${label}</a></div>`;}
function productCard(p){return offerCard(p,{favoriteControl:`<button class="favorite ${favorites.includes(p.id)?'saved':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="Сохранить ${esc(offerFor(p).title)}">${favorites.includes(p.id)?'★':'☆'}</button>`});}
function catalog(){let list=products.filter(p=>p.status==='published'&&(path()!=='favorites'||favorites.includes(p.id)));list=list.filter(p=>(category==='Все'||p.category===category)&&`${p.title} ${p.description} ${offerFor(p).title} ${offerFor(p).audience}`.toLowerCase().includes(filter.toLowerCase()));list.sort(sort==='rating'?(a,b)=>b.assessment.rank-a.assessment.rank:sort==='price'?(a,b)=>a.priceCents-b.priceCents:(a,b)=>b.assessment.rank-a.assessment.rank);
shell(`${path()==='favorites'?heading('Сохранённые решения','Продукты, к которым удобно вернуться.'): `<section class="hero"><div><div class="eyebrow">ВЫБЕРИТЕ КОНКРЕТНУЮ ВЫГРУЗКУ</div><h1>Что нужно вашей команде?</h1><p>Компании для продаж, объявления для рекламного брифа, публикации для контент-плана. Откройте продукт: посмотрите пример файла, задайте параметры и проверьте стоимость одного сбора.</p><a class="secondary" href="#assistant">Нужна помощь с выбором →</a></div></section>`}<div class="toolbar"><input id="catalog-search" type="search" placeholder="Например: компании, реклама, SMM, SEO" value="${esc(filter)}" aria-label="Поиск продуктов"><select id="catalog-sort" aria-label="Сортировка"><option value="popular" ${sort==='popular'?'selected':''}>Выбор Affsiwen</option><option value="rating" ${sort==='rating'?'selected':''}>По редакционной оценке</option><option value="price" ${sort==='price'?'selected':''}>По цене</option></select></div><div class="tabs">${['Все',...new Set(products.filter(p=>p.status==='published').map(p=>p.category))].map(c=>`<button class="tab ${category===c?'active':''}" data-action="category" data-value="${esc(c)}">${esc(c)}</button>`).join('')}<span class="page-count">${list.length} решений</span></div><div class="grid offer-grid">${list.map(productCard).join('')}</div>${!list.length?empty('Ничего не найдено','Измените запрос или категорию.'):''}<p class="fine" style="margin-top:24px">Оценка Affsiwen — предварительное редакционное суждение на основе открытых данных. Это не отзывы наших покупателей, подтверждение продаж или гарантия качества. <a href="#methodology">Методика →</a></p>`);}
function productPage(p){if(!p)return shell(empty('Продукт недоступен','Он ещё проходит отбор или был приостановлен.'));const o=offerFor(p);
shell(`<a class="back" href="#catalog">← В каталог</a><div class="split"><section><div class="eyebrow">${esc(o.audience)}</div><h1>${esc(o.title)}</h1><p class="offer-lead">${esc(o.purpose)}</p><div class="panel"><h2>Что входит в заказ</h2><dl class="offer-brief"><dt>Вы указываете</dt><dd>${esc(o.input)}. Например: ${esc(o.inputExample)}.</dd><dt>Мы собираем</dt><dd>До ${p.maxItems} ${esc(o.unit)} по вашим параметрам за один запуск.</dd><dt>Вы получаете</dt><dd>${esc(o.output)} Формат: таблица в кабинете, CSV и JSON.</dd><dt>Как использовать</dt><dd>${esc(o.use)}</dd></dl><div class="quality">${esc(o.limit)} Объём — верхний предел, а не гарантия наличия такого количества данных.</div></div>${offerPreview(p)}<div class="panel"><h2>Оценка Affsiwen</h2><p>${esc(p.assessment.label)}. ${esc(p.assessment.basis)}</p><p>Наблюдение: ${esc(p.assessment.observedAt||'не зафиксировано')}. Качество контрольного запуска: ${p.assessment.verifiedQuality?'проверено оператором':'пока не подтверждено'}. Оценка не является отзывом покупателя или обещанием результата.</p><a class="text-button" href="#methodology">Посмотреть методику →</a></div></section><aside class="panel sticky"><div class="eyebrow">НАСТРОИТЬ СБОР</div><h2>Параметры вашей выгрузки</h2><a class="text-button" href="#assistant">Помочь с выбором и параметрами →</a><form id="purchase" data-id="${p.id}"><label>${esc(o.input)}<textarea name="query" required minlength="2" maxlength="2000" placeholder="${esc(p.example)}">${esc(pendingOrder?.productId===p.id?pendingOrder.input.query:'')}</textarea></label><div class="form-grid"><label>Максимум записей<input type="number" name="limit" min="1" max="${p.maxItems}" value="${pendingOrder?.productId===p.id?pendingOrder.input.limit:p.maxItems}" required></label><label>Страна<select name="country">${['Worldwide','LU','DE','FR','ES','GB','US'].map(c=>`<option ${pendingOrder?.input.country===c?'selected':''}>${c}</option>`).join('')}</select></label></div><button class="text-button" type="button" data-action="example" data-id="${p.id}">Подставить пример</button><div class="cost"><span>До ${p.maxItems} записей / один запуск</span><strong>${money(p.priceCents)}</strong><span>Режим</span><strong>Демонстрационный</strong></div><button class="primary full" type="submit">${user?'Создать заказ':'Войти и продолжить'} · ${money(p.priceCents)}</button><p class="fine">Цена пока не утверждена по реальной себестоимости. В демо создаётся до 12 синтетических строк. Деньги не списываются.</p></form></aside></div>`);}
function authDestination(){if(path()==='login/supplier')return user?.role==='supplier'||user?.role==='operator'?'partner/apply':'start/supplier';if(path()==='login/operator')return user?.role==='operator'?'start/operator':'home';if(pendingOrder&&user?.role==='buyer')return `product/${pendingOrder.productId}`;return user?.role==='operator'?'start/operator':user?.role==='supplier'?'start/supplier':'assistant';}
function login(){if(path()==='login/supplier')sessionStorage.setItem('affsiwen-login-intent','supplier');else sessionStorage.removeItem('affsiwen-login-intent');shell(`<section class="panel auth"><div class="eyebrow">AFFSIWEN WORKSPACE</div><h1>${path()==='login/supplier'?'Вход для партнёра':path()==='login/operator'?'Вход для команды':'Добро пожаловать'}</h1><p>${path()==='login/supplier'?'Войдите, чтобы отправить подготовленную заявку.':path()==='login/operator'?'Используйте назначенный аккаунт оператора. Эта форма не предоставляет новые права.':'Заказы, результаты и история — в одном аккаунте.'}</p>${path().includes('google-error')?'<div class="banner">Google не подтвердил вход. Повторите попытку. Если такой email уже зарегистрирован, используйте пароль.</div>':''}${health.googleLogin?`<a class="secondary full google-login" href="/api/auth/google/start?role=${path()==='login/supplier'?'supplier':'buyer'}"><b>G</b> Продолжить с Google</a>`:'<button class="secondary full google-login" disabled><b>G</b> Продолжить с Google</button><p class="fine">Вход Google ещё не подключён на этом стенде.</p>'}<div class="auth-divider">или по email</div><form id="auth"><label>Email<input name="email" type="email" autocomplete="username" required></label><label>Пароль<input name="password" type="password" minlength="12" maxlength="128" autocomplete="current-password" required></label><label>Тип нового аккаунта<select name="role"><option value="buyer">Покупатель</option><option value="supplier" ${path()==='login/supplier'?'selected':''}>Партнёр: предложить Agent</option></select></label><div class="actions"><button class="primary" name="intent" value="login">Войти</button><button class="secondary" name="intent" value="register">Зарегистрироваться</button></div></form>${health.demoAccess?`<div class="login-demo"><p>Локальная проверка трёх ролей</p>${['buyer','operator','supplier'].map(r=>`<button class="secondary" data-action="demo-login" data-role="${r}">${roles[r]}</button>`).join('')}<p class="fine">Только этот локальный стенд. Внешний доступ к таким входам запрещён сервером.</p></div>`:''}<p class="fine">Публичный запуск и восстановление по email пока не включены.</p></section>`);}
function orderRow(o){return `<div class="list-row"><div>${status(o.status)}<h3 style="margin-top:10px"><a href="#order/${o.id}">${esc(o.product?.title||'Реклама конкурентов в Meta')}</a></h3><p>${esc(o.input.query||'Сбор рекламы')} · ${date(o.created)}</p></div><div class="actions"><strong>${money(o.amountCents)}</strong><a class="secondary" href="#order/${o.id}">Открыть →</a></div></div>`;}
async function orderList(){orders=(await api('orders')).orders;shell(heading(user.role==='operator'?'Все заказы':'Ваши заказы','От параметров до результата — вся история исполнения здесь.','<a class="primary" href="#catalog">Новый заказ ＋</a>')+(orders.length?`<div class="panel">${orders.map(orderRow).join('')}</div>`:empty('Начните с нужного результата','Выберите продукт из каталога и задайте параметры сбора.')));}
async function orderPage(id){const [a,b,c]=await Promise.all([api(`orders/${id}`),api(`orders/${id}/events`),api(`orders/${id}/messages`)]);const o=a.order;orders=[...orders.filter(x=>x.id!==id),o];const ready=['delivered','accepted'].includes(o.status);const stage=['awaiting_payment','queued','running','delivered','accepted'].indexOf(o.status==='starting'?'running':o.status);const events={'order.created':'Заказ сохранён','payment.fixture_confirmed':'Тестовая оплата подтверждена','provider.start_requested':'Запрос на запуск','provider.started':'Исполнение начато','result.delivered':'Результат проверен и выдан','buyer.accepted':'Покупатель принял результат','buyer.disputed':'Запрошена проверка','refund.fixture_confirmed':'Тестовый возврат выполнен','result.review':'Выдача требует проверки','operator.reread_existing_run':'Повторное чтение существующего запуска'};
shell(`<a class="back" href="#orders">← К заказам</a>${heading(esc(o.product?.title||'Реклама конкурентов в Meta'),`Заказ ${esc(o.id.slice(0,8))} · ${date(o.created)}`,status(o.status))}<div class="steps">${['Заказ','Оплата','Исполнение','Результат','Приёмка'].map((s,i)=>`<div class="step ${i<=stage?'done':''}">${i+1}. ${s}</div>`).join('')}</div>${o.error?`<div class="banner">${esc(o.error)}</div>`:''}<div class="split"><section><div class="panel"><div class="result-toolbar"><h2>Параметры заказа</h2><strong>${money(o.amountCents)}</strong></div><p>${esc(o.input.query||JSON.stringify(o.input.competitors))}</p><div class="meta">${esc(o.input.country)} · до ${o.input.limit||300} записей · версия продукта ${o.product?.version||1}</div><div class="actions" style="margin-top:24px">${o.status==='awaiting_payment'&&user.role==='buyer'?`<button class="primary" data-action="${health.payments==='stripe_test'?'checkout':'pay-test'}" data-id="${o.id}">${health.payments==='stripe_test'?'Оплатить в Stripe sandbox':'Подтвердить демооплату'}</button>${o.paymentMode==='fixture'?`<button class="secondary" data-action="cancel" data-id="${o.id}">Отменить заказ</button>`:''}`:''}${o.status==='delivered'&&user.role==='buyer'?`<button class="primary" data-action="accept" data-id="${o.id}">Принять результат</button>`:''}${ready?`<a class="secondary" href="/api/orders/${o.id}/csv">Скачать CSV ↓</a><a class="secondary" href="/api/orders/${o.id}/export">JSON ↓</a>`:''}${o.product&&user.role==='buyer'?`<button class="secondary" data-action="repeat" data-id="${o.id}">Повторить сбор</button>`:''}<button class="text-button" data-action="refresh">Обновить статус</button></div></div>${ready?`<div class="result-toolbar"><h2>${o.result.length} записей <small>· ${o.providerMode==='fixture'?'синтетические данные':'результат исполнителя'}</small></h2><input id="result-search" type="search" placeholder="Найти в результатах" value="${esc(resultFilter)}" aria-label="Поиск в результатах"></div><div id="results-table">${resultTable(o.result)}</div>${user.role==='buyer'?`<details class="panel" style="margin-top:20px"><summary>Проблема с результатом?</summary><form id="dispute" data-id="${o.id}"><label>Что нужно проверить<textarea name="reason" required minlength="5" maxlength="2000"></textarea></label><button class="secondary">Отправить на проверку</button></form></details>`:''}`:empty('Результат появится здесь',o.status==='awaiting_payment'?'Подтвердите тестовую оплату, чтобы запустить исполнение.':'Заказ сохраняется в базе. Можно закрыть страницу и вернуться позже.','#orders','К списку заказов')}<div class="panel" style="margin-top:22px"><h2>Обсуждение заказа</h2><div class="messages">${c.messages.map(m=>`<div class="message"><small>${roles[m.role]} · ${date(m.created)}</small>${esc(m.body)}</div>`).join('')||'<p>Сообщений пока нет. Напишите, если нужна помощь.</p>'}</div><form id="message" data-id="${o.id}"><label>Сообщение<textarea name="body" maxlength="4000" required></textarea></label><button class="primary">Отправить</button></form></div></section><aside><div class="panel"><h2>История</h2><ul class="timeline">${b.events.map(x=>`<li>${esc(events[x.event]||x.event)}<small>${date(x.created)}</small></li>`).join('')}</ul></div>${user.role==='operator'?`<div class="panel"><h2>Контроль исполнителя</h2><p>Режим: ${esc(o.providerMode||'не запущен')}<br>Run: ${esc(o.runId||'—')}<br>Полная себестоимость: ${o.costEurCents===undefined?'не измерена':money(o.costEurCents)}</p><div class="actions">${['review','delivered','accepted'].includes(o.status)&&o.paymentMode==='fixture'?`<button class="secondary" data-action="refund-test" data-id="${o.id}">Тестовый возврат</button>`:''}${o.status==='review'&&o.runId?`<button class="secondary" data-action="reread" data-id="${o.id}">Перечитать этот запуск</button>`:''}</div><p class="fine">Повторное чтение не создаёт новый платный запуск. Неопределённый старт требует сверки у исполнителя.</p></div>`:''}</aside></div>`);window.affsiwenRows=o.result||[];}
function resultTable(rows){const filtered=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(resultFilter.toLowerCase()));if(!filtered.length)return '<div class="empty">Нет подходящих записей.</div>';const keys=[...new Set(rows.flatMap(Object.keys))].filter(k=>k!=='synthetic').slice(0,10);return `<div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${filtered.slice(0,100).map(r=>`<tr>${keys.map(k=>`<td>${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function proposal(){return `<div class="panel"><div class="eyebrow">ДЛЯ ПАРТНЁРОВ</div><h2>Предложите свой Agent</h2><p>Подготовьте описание, пример входного задания и состав результата. Черновик можно заполнить до регистрации.</p><a class="primary" href="#partner/apply">Подготовить заявку</a><p class="fine">${Object.keys(partnerDraft).length?'У вас есть сохранённый черновик в этой вкладке.':'Подача заявки не публикует продукт автоматически.'}</p><a class="text-button" href="#start/supplier">Как проходит отбор</a></div>`;}
function sourcing(){const list=user.role==='supplier'?products.filter(p=>p.ownerId===user.id):products;shell(heading(user.role==='supplier'?'Ваши продукты':'Отбор и управление ассортиментом','Отбираем кандидатов по сигналам использования. Доступ к реальным продажам — после проверки прав, качества и расходов.')+`<div class="work-onboarding"><div><h3>${user.role==='supplier'?'Ваш следующий шаг':'Маршрут оператора'}</h3><p>${user.role==='supplier'?'Подготовьте заявку и следите за решением команды.':'Проверьте продукт, затем исполнение и экономику.'}</p></div><a class="secondary" href="#start/${user.role==='supplier'?'supplier':'operator'}">Все этапы</a></div><div class="split"><section><div class="supply-grid">${list.map(p=>`<article class="panel">${status(p.status)}<h3>${esc(p.title)}</h3><div class="source">Agent Affsiwen · ${esc(p.id)}</div><p>${esc(p.description)}</p>${p.status==='published'?`<a class="text-button" href="${esc(p.url)}">Страница продукта →</a>`:''}<div class="evidence">${esc(p.assessment.label)}</div>${p.reviewNote?`<div class="quality"><strong>Комментарий команды</strong><br>${esc(p.reviewNote)}</div>`:''}${p.submission?`<details><summary>Ваша заявка</summary><p><strong>Для кого:</strong> ${esc(p.submission.audience)}</p><p><strong>Пример задания:</strong> ${esc(p.submission.inputExample)}</p><p><strong>Поля:</strong> ${esc(p.submission.outputFields)}</p><p><strong>Ограничения:</strong> ${esc(p.submission.limitations)}</p></details>`:''}<details><summary>До коммерческой продажи: ${(p.readiness.missing||[]).length} проверок</summary><ul class="checklist">${(p.readiness.missing||[]).map(v=>`<li><span>○</span>${esc(v)}</li>`).join('')}</ul></details>${user.role==='operator'?`<form class="product-edit" data-id="${p.id}" data-version="${p.version}"><label>Цена демопакета, EUR<input type="number" min="1" max="1000" step="0.01" name="price" value="${p.priceCents/100}" required></label><label>Комментарий партнёру<textarea name="reviewNote" maxlength="2000" placeholder="Что уточнить или почему принято решение">${esc(p.reviewNote||'')}</textarea></label><div class="actions"><button class="primary" name="status" value="published">${p.status==='published'?'Сохранить':'В демокаталог'}</button><button class="secondary" name="status" value="paused">Пауза</button><button class="text-button" name="status" value="rejected">Отклонить</button></div></form>`:''}</article>`).join('')||empty('Заявок пока нет','Предложите Agent, который решает понятную задачу покупателя.','#partner/apply','Добавить заявку')}</div></section><aside>${proposal()}<div class="panel"><h2>Что считаем доказательством</h2><p>Пользователи, оценки и отзывы помогают отобрать кандидатов. Продажи автора и динамика спроса пока неизвестны.</p><p>После подключения измеряем оплату, успешную выдачу, повторы, возвраты и маржу уже у Affsiwen.</p><p>Подтверждение продукта доступно через защищённый API квалификации после реального контрольного запуска. Публикация в демокаталоге этих проверок не заменяет.</p><p>Партнёр не видит клиентские заказы. За покупку, поддержку и выдачу результата отвечает Affsiwen.</p></div></aside></div>`);}
async function analytics(){const d=await api('operations');shell(heading('Экономика и сигналы спроса','Тестовые заказы отдельно от коммерческой выручки. Неизвестные расходы не считаем нулевыми.')+`<div class="stats"><div class="stat"><span>Реальная выручка</span><strong>${money(d.commercialRevenueCents)}</strong><small>Продажи не включены</small></div><div class="stat"><span>Тестовый оборот за вычетом возвратов</span><strong>${money(d.testVolumeCents)}</strong><small>Не реальные деньги</small></div><div class="stat"><span>Всего заказов</span><strong>${d.orders}</strong></div><div class="stat"><span>Расходы не сверены</span><strong>${d.costUnknown}</strong><small>Маржа не подтверждена</small></div></div><div class="table-wrap"><table><thead><tr><th>Продукт</th><th>Заказы</th><th>Тестовые оплаты*</th><th>Выдано</th><th>Повторные покупатели · тест</th><th>Реальные оплаты</th></tr></thead><tbody>${d.products.map(p=>`<tr><td>${esc(p.title)}</td><td>${p.orders}</td><td>${p.testPaid}</td><td>${p.delivered}</td><td>${p.repeatBuyers}</td><td>${p.commercialPaid}</td></tr>`).join('')}</tbody></table></div><p class="fine">* Включая впоследствии возвращённые тестовые оплаты.</p><div class="panel" style="margin-top:22px"><h2>Считать перед масштабированием</h2><p>Цена без налогов − полная стоимость Agent − комиссии оплаты − хранение − возвраты − поддержка − привлечение клиента.</p><p>Сценарные €19 в каталоге не являются утверждённым прайсом. Для каждого продукта сначала нужен контрольный платный запуск и сверка фактического счёта.</p></div>`);}
async function operations(){const d=await api('operations');orders=(await api('orders')).orders;shell(heading('Операционный контроль','Очередь, проблемные выдачи и обращения клиентов.')+`<div class="stats"><div class="stat"><span>В работе</span><strong>${d.queued}</strong></div><div class="stat"><span>Требуют проверки</span><strong>${d.needsReview}</strong></div><div class="stat"><span>Каталог</span><strong>${products.filter(p=>p.status==='published').length}</strong></div><div class="stat"><span>Кандидаты</span><strong>${products.filter(p=>p.status==='candidate').length}</strong></div></div><div class="panel"><h2>Заказы</h2>${orders.sort((a,b)=>Number(['review','reconciliation'].includes(b.status))-Number(['review','reconciliation'].includes(a.status))).map(orderRow).join('')||'<p>Очередь пока пуста.</p>'}</div>`);}
async function launch(){const d=await api('launch');shell(heading('Инфраструктура и запуск','Статус платформы без подмены подключений демонстрацией.')+`<div class="panel">${d.items.map(i=>`<div class="list-row"><div><h3>${esc(i.name)}</h3><p>${esc(i.note)}</p></div><span class="pill ${i.status==='ready'?'green':'amber'}">${i.status==='ready'?'Готово':'Не подключено / не завершено'}</span></div>`).join('')}</div>`);}

function methodology(){shell(heading('Как Affsiwen оценивает решения','Редакционная оценка, а не рейтинг покупателей.')+`<section class="panel"><h2>Что означает наша отметка</h2><p>Это субъективная предварительная оценка команды Affsiwen, опирающаяся на открытые интернет-данные: признаки использования и объём обратной связи. Мы не выдаём чужие отзывы или пользователей за клиентов Affsiwen и не делаем выводов о продажах автора.</p><h3>Методика v1</h3><p>«Приоритет для проверки»: в зафиксированной публичной выборке есть не менее 100 отзывов. «Требует дополнительной проверки»: отзывов меньше. «Недостаточно данных»: наблюдение не зафиксировано. Порог 100 — наш редакционный критерий, а не научно доказанная граница качества. Количество отзывов само по себе не означает положительную оценку.</p><p>Дату наблюдения и статус контрольного запуска показываем отдельно. Исходные наблюдения хранятся во внутренней базе Affsiwen. Доступные наблюдения для стартового каталога датированы 30.09.2026; они не обновляются в реальном времени.</p><h3>Что оценка не доказывает</h3><p>Платный спрос, отсутствие накруток, стабильность исполнения, права на использование данных и вашу будущую прибыль. До коммерческой продажи нужны отдельные проверки качества, условий и себестоимости.</p></section>`);}
async function sendIntake(message){intakeText=message;const form=document.querySelector('#intake');if(form){form.setAttribute('aria-busy','true');form.querySelector('button[type=submit]').textContent='Уточняем задачу…';}try{intakeState=await api('onboarding',{message,requestId:intakeRequest});intakeText='';intakeRequest=crypto.randomUUID();await assistantPage();}finally{if(form){form.removeAttribute('aria-busy');form.querySelector('button[type=submit]').textContent='Продолжить →';}}}
async function assistantPage(){intakeState=await api('onboarding');const a=intakeState.answer,r=a?.recommendation;const examples=['Нужны рестораны в Люксембурге для предложения наших услуг','Хочу изучить рекламу конкурентов','Нужно сравнить поисковую выдачу'];shell(`<section class="intake-hero"><div class="eyebrow">AFFSIWEN / ПОДБОР ПОД ВАШУ ЗАДАЧУ</div><h1>Какую задачу решаем?</h1><p>Поможем выбрать данные и Agent. Вам не нужно разбираться в техническом каталоге.</p><div class="intake-steps"><span>01 · Ваша задача</span><span>02 · Уточняем детали</span><span>03 · Проверяете заказ</span></div></section><div class="split intake-layout"><section class="panel"><div class="result-toolbar"><h2>Помощник Affsiwen</h2><span class="pill ${intakeState.mode==='llm'?'blue':'amber'}">${intakeState.mode==='llm'?'AI-подбор':'Демо диалога · без LLM'}</span></div><div class="intake-chat" aria-live="polite">${intakeState.messages.length?intakeState.messages.map(m=>`<div class="intake-bubble ${m.role==='user'?'mine':''}"><small>${m.role==='user'?'Вы':'Affsiwen'}</small><div>${esc(m.content)}</div></div>`).join(''):'<div class="intake-bubble"><small>Affsiwen</small><div>Какую задачу вы решаете? Например: найти компании для продаж, изучить рекламу конкурентов или собрать контент для исследования.</div></div>'}</div>${!r?`<div class="intake-options">${(a?.options?.length?a.options:!a?examples:[]).map(v=>`<button class="secondary" data-action="intake-option" data-value="${esc(v)}">${esc(v)}</button>`).join('')}</div>`:''}<form id="intake"><label for="intake-message">${r?'Хотите уточнить задачу?':'Опишите задачу своими словами'}<textarea id="intake-message" name="message" required minlength="2" maxlength="2000" placeholder="Что вы продаёте, кого ищете и какой результат нужен…">${esc(intakeText)}</textarea></label><div class="actions"><button class="primary" type="submit">Продолжить →</button><button class="text-button" type="button" data-action="intake-reset">Новая задача</button></div><p class="fine">Не отправляйте пароли, ключи доступа или конфиденциальные данные. ${intakeState.mode==='llm'?'Сообщения обрабатывает AI-провайдер OpenAI для подбора продукта.':'Сейчас ответы формирует ограниченный демонстрационный сценарий. LLM API ещё не подключён.'} Диалог доступен в этом браузере в течение 24 часов.</p></form></section><aside>${r?`<section class="panel recommendation"><span class="pill blue">РЕКОМЕНДАЦИЯ ДЛЯ ВАШЕЙ ЗАДАЧИ</span><h2>${esc(r.title)}</h2><p>${esc(a.message)}</p><h3>Что получите</h3><p>${esc(r.deliverable)}</p><div class="quality">${esc(r.limitations)}</div><div class="brief"><h3>Параметры заказа</h3><p>${esc(r.input.query)}</p><div class="meta">${esc(r.input.country)} · до ${r.input.limit} записей · CSV + JSON</div></div><div class="cost"><span>Сценарная цена</span><strong>${money(r.priceCents)}</strong></div><button class="primary full" data-action="intake-apply">Проверить и настроить заказ →</button><a class="text-button" href="${esc(r.url)}">Открыть продукт</a><p class="fine">Рекомендация ничего не покупает и не запускает. Параметры можно изменить перед созданием заказа. В демо — синтетические данные.</p></section>`:`<section class="panel intake-explainer"><div class="product-icon">✧</div><h2>Начинаем с результата</h2><p>Помощник уточнит, какие данные вам нужны, для какого рынка и в каком объёме.</p><ul class="checklist"><li><span>01</span>Подберёт из доступных Agents</li><li><span>02</span>Объяснит, что будет в выдаче</li><li><span>03</span>Подготовит параметры заказа</li></ul><p>Если готового решения нет, скажем об этом. Финальное решение о заказе принимаете вы.</p><a class="text-button" href="#catalog">Я знаю, что нужно — открыть каталог →</a></section>`}</aside></div>`);}
function homePage(){document.title='Affsiwen — продукты по площадкам';root.innerHTML=publicShell(amazonHome(),{user});}
function startPage(role){document.title='Affsiwen — начало работы';root.innerHTML=publicShell(roleWelcome(role,{user,health}),{user,active:role});}
function partnerPage(){root.innerHTML=publicShell(partnerWizard({step:partnerStep,draft:partnerDraft,user}),{user,active:'supplier'});}
async function load(){products=(await api('catalog')).products;if(user)favorites=(await api('favorites')).ids;}
async function render(){const revision=++routeRevision;try{await load();if(revision!==routeRevision)return;const [page,id]=path().split('/');if(!user&&!['home','start','partner','assistant','methodology','catalog','e-commerce','travel','real-estate','financial','finance','most-popular','popular','social-media','social','product','login','resume'].includes(page)){location.hash=page==='supply'?'login/supplier':'login';return;}if(['sourcing','operations','analytics','economics','launch'].includes(page)&&user?.role!=='operator'){shell(empty('Нет доступа','Этот раздел доступен оператору Affsiwen.'));return;}if(page==='resume'){const intent=sessionStorage.getItem('affsiwen-login-intent');sessionStorage.removeItem('affsiwen-login-intent');location.hash=intent==='supplier'?(user?.role==='supplier'?'partner/apply':'start/supplier'):pendingOrder?`product/${pendingOrder.productId}`:'assistant';return;}if(page==='home')homePage();else if(page==='start')startPage(id);else if(page==='partner'&&id==='apply')partnerPage();else if(page==='assistant')await assistantPage();else if(page==='methodology')methodology();else if(page==='e-commerce'||page==='catalog'){document.title='E-commerce — Affsiwen';root.innerHTML=publicShell(ecommercePage(),{user,active:'catalog'});}else if(page==='travel'){document.title='Travel — Affsiwen';root.innerHTML=publicShell(travelPage(),{user,active:'travel'});}else if(page==='real-estate'){document.title='Real Estate — Affsiwen';root.innerHTML=publicShell(realEstatePage(),{user,active:'estate'});}else if(page==='financial'||page==='finance'){document.title='Financial — Affsiwen';root.innerHTML=publicShell(financialPage(),{user,active:'financial'});}else if(page==='most-popular'||page==='popular'){document.title='Most Popular — Affsiwen';root.innerHTML=publicShell(popularPage(),{user,active:'popular'});}else if(page==='social-media'||page==='social'){document.title='Social Media — Affsiwen';root.innerHTML=publicShell(socialPage(),{user,active:'social'});}else if(page==='favorites')catalog();else if(page==='product'&&commerceProduct(id))await openAmazon(id);else if(page==='product')productPage(products.find(p=>p.id===id&&p.status==='published'));else if(page==='login')login();else if(page==='orders')await orderList();else if(page==='order')await orderPage(id);else if(page==='sourcing'||page==='supply')sourcing();else if(page==='economics')shell(heading('Расчёт цены Agent','Внутренний инструмент Affsiwen. Значения — сценарии, не измеренные расходы.')+economicsForm());else if(page==='analytics')await analytics();else if(page==='operations')await operations();else if(page==='launch')await launch();else shell(empty('Страница не найдена','Вернитесь в каталог.'));}catch(e){toast(e.message,true);if(!root.querySelector('main'))shell(empty('Сервер недоступен','Запустите сервер Affsiwen. Статический хостинг не исполняет заказы.'));}}
root.addEventListener('submit',async ev=>{ev.preventDefault();if(busy)return;busy=true;const f=ev.target,data=Object.fromEntries(new FormData(f));const buttons=[...f.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{
 if(f.id==='amazon-chat'){await sendAmazon(data.message);}
 else if(f.id==='partner-wizard'){
  if(partnerStep<3){partnerDraft={...partnerDraft,...data};partnerStep++;savePartner();partnerPage();window.scrollTo(0,0);}
  else if(!user||!['supplier','operator'].includes(user.role)){savePartner();if(user){await api('logout',{});user=null;favorites=[];}location.hash='login/supplier';}
  else{await api('catalog',{...partnerDraft,submission:{audience:partnerDraft.audience,inputExample:partnerDraft.inputExample,outputFields:partnerDraft.outputFields,limitations:partnerDraft.limitations}});partnerDraft={};partnerStep=1;sessionStorage.removeItem('affsiwen-partner-draft');location.hash=user.role==='operator'?'sourcing':'supply';toast('Заявка отправлена. Статус: на отборе.');}
 }
 else if(f.id==='economics'){const quote=await api('economics/quote',Object.fromEntries(Object.entries(data).map(([k,v])=>[k,Number(v)])));document.querySelector('#economics-result').innerHTML=economicsResult(quote);}
 else if(f.id==='intake'){await sendIntake(data.message);}
 else if(f.id==='auth'){if(ev.submitter.value==='register'){const registration=await api('register',data);if(registration.confirmationRequired){toast('Проверьте почту: подтвердите адрес, затем войдите.');return;}}user=(await api('login',data)).user;location.hash=authDestination();await render();}
 else if(f.id==='purchase'){pendingOrder={productId:f.dataset.id,input:{...data,limit:Number(data.limit)}};saveDraft();if(!user){location.hash='login';return;}if(user.role!=='buyer')throw Error('Войдите в аккаунт покупателя для заказа.');const o=(await api('orders',{...pendingOrder,key:pendingKey})).order;pendingKey=crypto.randomUUID();pendingOrder=null;saveDraft();location.hash=`order/${o.id}`;}
 else if(f.id==='proposal'){await api('catalog',data);toast('Agent добавлен в отбор.');await render();}
 else if(f.classList.contains('product-edit')){await api(`catalog/${f.dataset.id}`,{version:Number(f.dataset.version),priceCents:Math.round(Number(data.price)*100),status:ev.submitter.value,reviewNote:data.reviewNote});toast('Каталог обновлён на сервере.');await render();}
 else if(f.id==='message'){await api(`orders/${f.dataset.id}/messages`,data);await render();}
 else if(f.id==='dispute'){await api(`orders/${f.dataset.id}/dispute`,data);await render();}
}catch(e){toast(e.message,true);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}});
root.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||busy)return;const a=b.dataset.action;busy=true;try{
 if(a==='amazon-suggestion'){await sendAmazon(b.dataset.value);}
 else if(a==='amazon-remove-image'){amazonState.image=null;amazonRequestId=crypto.randomUUID();drawAmazon();}
 else if(a==='amazon-reset'){const cleared=await api(commercePath()+'/chat/reset',{});amazonState={...amazonState,...cleared,text:'',error:'',image:null};amazonRequestId=crypto.randomUUID();drawAmazon();}
 else if(a==='amazon-run'){
  const current=activeCommerceId,base=commercePath();
  if(!amazonState.plan)throw Error('Подготовьте запрос.');amazonState.launching=true;amazonState.error='';drawAmazon();
  try{const response=await api(base+'/run',{planId:amazonState.plan.id,confirm:true});if(current!==activeCommerceId||!onCommercePage())return;amazonState.run=response.run;amazonState.result=response.run?.result||null;amazonPollCount=0;}
  catch(e){if(current===activeCommerceId&&onCommercePage()){amazonState.error=e.message;try{const restored=await api(base+'/workspace');if(current===activeCommerceId&&onCommercePage())amazonState={...amazonState,...restored};}catch{}}}
  finally{if(current===activeCommerceId&&onCommercePage()){amazonState.launching=false;drawAmazon();scheduleAmazonPoll();}}
 }
 else if(a==='amazon-poll'){busy=false;await pollAmazon();}
 else if(a==='amazon-demo'){if(!amazonState.plan)throw Error('Сначала подготовьте запрос.');const response=await api(commercePath()+'/demo',{planId:amazonState.plan.id});amazonState={...amazonState,...response};drawAmazon();root.querySelector('.amazon-result')?.scrollIntoView({behavior:'smooth'});}
 else if(a==='focus-main'){ev.preventDefault();document.querySelector('#page-content')?.focus();}
 else if(a==='landing-example'){landingExample=b.dataset.value;homePage();root.querySelector(`[data-action="landing-example"][data-value="${landingExample}"]`)?.focus({preventScroll:true});}
 else if(a==='landing-role'){landingRole=b.dataset.value;homePage();root.querySelector(`[data-action="landing-role"][data-value="${landingRole}"]`)?.focus({preventScroll:true});}
 else if(a==='landing-try'){const example=examples[b.dataset.value];if(!example)throw Error('Выберите пример задачи.');await api('onboarding/reset',{});intakeText=example.query;intakeRequest=crypto.randomUUID();intakeState=await api('onboarding',{message:intakeText,requestId:intakeRequest});intakeText='';intakeRequest=crypto.randomUUID();location.hash='assistant';}
 else if(a==='partner-back'){const f=root.querySelector('#partner-wizard');if(f)partnerDraft={...partnerDraft,...Object.fromEntries(new FormData(f))};partnerStep=Math.max(1,partnerStep-1);savePartner();partnerPage();}
 else if(a==='intake-option'){await sendIntake(b.dataset.value);}
 else if(a==='intake-reset'){await api('onboarding/reset',{});intakeText='';intakeRequest=crypto.randomUUID();await assistantPage();}
 else if(a==='intake-apply'){const r=intakeState.answer?.recommendation;if(!r)throw Error('Подбор устарел. Повторите запрос.');pendingOrder={productId:r.productId,input:r.input};saveDraft();pendingKey=crypto.randomUUID();location.hash=`product/${r.productId}`;}
 else if(a==='category'){category=b.dataset.value;catalog();}
 else if(a==='example'){document.querySelector('[name=query]').value=products.find(p=>p.id===b.dataset.id).example;}
 else if(a==='logout'){await api('logout',{});user=null;favorites=[];pendingOrder=null;saveDraft();intakeState={messages:[],answer:null};location.hash='login';await render();}
 else if(a==='demo-login'){user=(await api('demo-session',{role:b.dataset.role})).user;location.hash=authDestination();await render();}
 else if(a==='favorite'){if(!user){location.hash='login';return;}favorites=(await api(`catalog/${b.dataset.id}/favorite`,{})).ids;catalog();}
 else if(a==='repeat'){const o=(await api(`orders/${b.dataset.id}`)).order;pendingOrder={productId:o.productId,input:o.input};pendingKey=crypto.randomUUID();saveDraft();location.hash=`product/${o.productId}`;}
 else if(a==='refresh')await render();
 else {const out=await api(`orders/${b.dataset.id}/${a}`,{});if(out.url){location.href=out.url;return;}await render();toast('Заказ обновлён.');}
}catch(e){toast(e.message,true);}finally{busy=false;}});
root.addEventListener('input',ev=>{if(ev.target.id==='amazon-message'){amazonState.text=ev.target.value;amazonRequestId=crypto.randomUUID();}if(ev.target.closest('#partner-wizard')&&ev.target.name){partnerDraft[ev.target.name]=ev.target.value;savePartner();}if(ev.target.id==='intake-message'){intakeText=ev.target.value;intakeRequest=crypto.randomUUID();}if(ev.target.id==='catalog-search'){filter=ev.target.value;const position=ev.target.selectionStart;catalog();const el=document.querySelector('#catalog-search');el.focus();el.setSelectionRange(position,position);}if(ev.target.id==='result-search'){resultFilter=ev.target.value;document.querySelector('#results-table').innerHTML=resultTable(window.affsiwenRows||[]);}});
root.addEventListener('change',ev=>{if(ev.target.id==='amazon-message'){amazonState.text=ev.target.value;amazonRequestId=crypto.randomUUID();}if(ev.target.id==='catalog-sort'){sort=ev.target.value;catalog();}});
window.addEventListener('hashchange',()=>{resultFilter='';window.scrollTo(0,0);render();});
try{health=await api('health');try{user=(await api('me')).user;}catch{}await render();}catch{root.innerHTML='<div class="loading"><h1>Сервер платформы не подключён</h1><p>Этот интерфейс работает с API и базой Affsiwen. Запустите сервер или откройте рабочий адрес платформы.</p><a href="http://127.0.0.1:4181/market.html">Открыть локальную платформу</a></div>';}
setInterval(async()=>{if(!user||busy||!path().startsWith('order/'))return;const id=path().split('/')[1];try{const o=(await api(`orders/${id}`)).order;const was=orders.find(x=>x.id===id);if(was&&was.status!==o.status){if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))await render();else toast('Статус заказа изменился: '+labels[o.status]+'. Нажмите «Обновить статус».');}orders=[...orders.filter(x=>x.id!==id),o];}catch{}},3000);

root.addEventListener('change',async ev=>{
 if(ev.target.id!=='amazon-photo')return;
 const file=ev.target.files?.[0];if(!file)return;
 try{
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Выберите JPEG, PNG или WebP до 10 МБ.');
  const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>50000000){bitmap.close();throw Error('Уменьшите разрешение фото: максимум 50 мегапикселей.');}
  const ratio=Math.min(1,1280/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  const encoded=canvas.toDataURL('image/jpeg',.82).split(',')[1];if(encoded.length>1400000)throw Error('Фото слишком большое. Выберите менее детальное изображение.');
  amazonState.image={mediaType:'image/jpeg',data:encoded};amazonState.error='';amazonRequestId=crypto.randomUUID();drawAmazon();
 }catch(e){amazonState.error=e.message;drawAmazon();}
});
